create database indexes_db;

use indexes_db;

CREATE TABLE employees (
    employee_id INT,
    employee_name VARCHAR(100),
    department VARCHAR(50),
    salary DECIMAL(10,2)
);

desc employees;

drop table employees;

CREATE TABLE employees (
    employee_id INT primary key,
    employee_name VARCHAR(100),
    department VARCHAR(50),
    salary DECIMAL(10,2),
    email varchar(30) unique
);

desc employees;

-- creating an index

create index idx_employee_name_employees 
on employees(employee_name);

create unique index idx_employee_name_employees_unique
on employees(employee_name);

show indexes from employees;

drop index idx_employee_name_employees
on employees;

create index idx_department_salary_employees
on employees(department, salary);


drop table employees;

CREATE TABLE employees (
    employee_id INT primary key,
    employee_name VARCHAR(100),
    department VARCHAR(50),
    salary DECIMAL(10,2),
    email varchar(30) unique
);

